    def get_level(x):
        if x == 1:
            return 0
        level = 0
        segment_length = 1
        while segment_length < x:
            level += 1
            segment_length *= 10
        return level

    def get_segment_level(l, r):
        if l == r:
            return 0
        level = 0
        segment_length = 10
        while True:
            if (r - l + 1) <= segment_length:
                return level
            level += 1
            segment_length *= 10

    def find_segments(L, R):
        segments = []
        current = L
        while current <= R:
            level = get_segment_level(current, R)
            segment_length = 10 ** (2 ** (level - 1)) if level > 0 else 1
            end = min(current + segment_length - 1, R)
            segments.append(level)
            current = end + 1
        return segments

